$ErrorActionPreference="Stop"
$D="$env:ProgramData\OfficeDeploy";$R="https://raw.githubusercontent.com/alamaxjashek/OfficeDeploy/main";New-Item $D -ItemType Directory -Force|Out-Null
$Log="$D\uninstall.log";Start-Transcript -Path $Log -Append -Force|Out-Null;$ExitCode=0
try{Write-Host "=== ETAPA 1: CERRANDO APLICACIONES OFFICE ===";$Apps=@("WINWORD","EXCEL","OUTLOOK","POWERPNT","MSACCESS","MSPUB","ONENOTE","VISIO","WINPROJ");foreach($A in $Apps){Get-Process $A -ErrorAction SilentlyContinue|Stop-Process -Force -ErrorAction SilentlyContinue};Invoke-WebRequest "$R/setup.exe" -OutFile "$D\setup.exe";Invoke-WebRequest "$R/uninstall.xml" -OutFile "$D\uninstall.xml";Write-Host "=== ETAPA 2: ELIMINANDO CLICK-TO-RUN CON ODT ===";$O=Start-Process "$D\setup.exe" -ArgumentList "/configure `"$D\uninstall.xml`"" -Wait -PassThru -NoNewWindow;Write-Host "ODT ExitCode: $($O.ExitCode)";if($O.ExitCode -notin @(0,3010)){Write-Warning "ODT devolvio codigo $($O.ExitCode)"}
$Roots=@("HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall","HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall");$Paths=$Roots|ForEach-Object{"$_\*"};$LegacyPattern="(?i)(Office|Visio|Project|Access|Excel|Word|PowerPoint|Outlook|Publisher|OneNote).*(2007|2010|2013|2016)";$GetLegacy={@(Get-ItemProperty -Path $Paths -ErrorAction SilentlyContinue|Where-Object{$_.Publisher -like "Microsoft*" -and $_.DisplayName -match $LegacyPattern -and $_.PSChildName -match "^\{[0-9A-Fa-f-]+\}$"})}
Write-Host "=== ETAPA 3: ELIMINANDO OFFICE MSI 2007-2016 ===";$Items=&$GetLegacy;foreach($I in ($Items|Sort-Object PSChildName -Unique)){Write-Host "Desinstalando: $($I.DisplayName) [$($I.PSChildName)]";$M=Start-Process msiexec.exe -ArgumentList "/x `"$($I.PSChildName)`" /qn /norestart" -Wait -PassThru;Write-Host "MSI ExitCode: $($M.ExitCode)"}
Write-Host "=== ETAPA 4: LIMPIANDO ENTRADAS HUERFANAS ===";$Left=&$GetLegacy;$Codes=@($Left.PSChildName|Sort-Object -Unique);foreach($C in $Codes){$T=Start-Process msiexec.exe -ArgumentList "/x `"$C`" /qn /norestart" -Wait -PassThru;if($T.ExitCode -eq 1605){Write-Host "Producto $C ya no esta instalado; eliminando entradas huerfanas...";$Left|Where-Object{$_.PSChildName -eq $C}|ForEach-Object{Write-Host "Eliminando registro huerfano: $($_.PSPath)";Remove-Item $_.PSPath -Recurse -Force -ErrorAction SilentlyContinue}}elseif($T.ExitCode -notin @(0,3010)){Write-Warning "No se pudo eliminar $C. MSI ExitCode: $($T.ExitCode)"}}
Write-Host "=== VERIFICACION FINAL ===";$Left=&$GetLegacy;if($Left.Count -gt 0){Write-Host "QUEDAN COMPONENTES OFFICE MSI:" -ForegroundColor Red;$Left|Select-Object DisplayName,DisplayVersion,PSChildName|Format-Table -AutoSize;$ExitCode=1}else{Write-Host "Office MSI antiguo eliminado correctamente." -ForegroundColor Green}}catch{Write-Host "ERROR: $($_.Exception.Message)" -ForegroundColor Red;$ExitCode=1}finally{Stop-Transcript -ErrorAction SilentlyContinue};exit $ExitCode